229	     * The owner's age band, derived from the {@link #birthDate} measured in completed years
230	     * against the {@link #registrationDate}: {@code "MINOR"} when under 18, {@code "ADULT"}
231	     * from 18 to 64, and {@code "SENIOR"} at 65 and over.
232	     *
233	     * @return the age band, or {@code null} when either the birth date or the registration
234	     *         date has not been assigned
235	     */
236	    public String getAgeBand() {
237	        if (this.birthDate == null || this.registrationDate == null) {
238	            return null;
239	        }
240	        int age = java.time.Period.between(this.birthDate, this.registrationDate).getYears();
241	        if (age < 18) {
242	            return "MINOR";
243	        }
244	        if (age < 65) {
245	            return "ADULT";
246	        }
247	        return "SENIOR";
248	    }
