382	    /**
383	     * The fiscal year of the (business-day-adjusted) {@link #registrationDate}, formatted as
384	     * {@code "FY<YY>"}. The fiscal year starts on 1 July: a registration date on or after 1 July
385	     * belongs to that calendar year's fiscal year, an earlier date belongs to the previous year's,
386	     * and {@code YY} is the last two digits of the year the fiscal year started (e.g. a date in
387	     * August 2026 yields {@code "FY26"}, a date in March 2026 yields {@code "FY25"}).
388	     *
389	     * @return the formatted fiscal year, or {@code null} if the registration date has not been
390	     *         assigned
391	     */
392	    public String getFiscalYear() {
393	        if (this.registrationDate == null) {
394	            return null;
395	        }
396	        return String.format("FY%02d", fiscalYearOf(this.registrationDate) % 100);
397	    }
398	
399	    /**
400	     * The starting calendar year of the fiscal year (which begins on 1 July) that the given date
401	     * falls in: the date's own year when it is on or after 1 July, otherwise the previous year.
402	     *
403	     * @param date the date whose fiscal year is derived (must not be {@code null})
404	     * @return the starting calendar year of the fiscal year
405	     */
406	    private static int fiscalYearOf(LocalDate date) {
407	        return date.getMonthValue() >= java.time.Month.JULY.getValue()
408	            ? date.getYear() : date.getYear() - 1;
409	    }
410	
411	    /**
412	     * The owner's membership number formatted as {@code "<customerCode>-M<YY>"}, where
413	     * {@code YY} is the last two digits of the registration date's fiscal year (the same fiscal
414	     * year returned by {@link #getFiscalYear()}, e.g. {@code "NSW-1A2B3C4D-M26"}).
415	     *
416	     * @return the formatted membership number, or {@code null} if the customer code or
417	     *         registration date has not been assigned
418	     */
419	    public String getMembershipNumber() {
420	        if (this.customerCode == null || this.registrationDate == null) {
421	            return null;
422	        }
423	        return String.format("%s-M%02d", this.customerCode, fiscalYearOf(this.registrationDate) % 100);
424	    }
425	
426	    /**
427	     * The owner's Luhn check digit: a single digit ({@code 0}-{@code 9}) computed with the
428	     * standard Luhn algorithm over the decimal digits contained in the {@code customerCode}
429	     * (non-digit characters are ignored).
430	     *
431	     * @return the Luhn check digit, or {@code null} if the customer code has not been assigned
432	     */
433	    public Integer getCheckDigit() {
434	        if (this.customerCode == null) {
435	            return null;
436	        }
437	        int sum = 0;
438	        boolean dbl = true;
439	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
440	            char c = this.customerCode.charAt(i);
441	            if (c < '0' || c > '9') {
442	                continue;
443	            }
444	            int d = c - '0';
445	            if (dbl) {
446	                d *= 2;
447	                if (d > 9) {
448	                    d -= 9;
449	                }
450	            }
451	            sum += d;
452	            dbl = !dbl;
453	        }
454	        return (10 - (sum % 10)) % 10;
455	    }
