523	    /**
524	     * The owner's identity key: the single derived value used for duplicate detection, formed as
525	     * {@code normalizedTelephone + "|" + (email or empty) + "|" + householdId}. The telephone and
526	     * email are the already-normalized stored values and a {@code null} email or household id is
527	     * rendered as the empty string. Two owners are duplicates only when their whole identity keys
528	     * are equal; because the telephone is part of the key, household members with different
529	     * telephones have different identity keys.
530	     *
531	     * @return the derived identity key
532	     */
533	    public String getIdentityKey() {
534	        String telephonePart = this.telephone == null ? "" : this.telephone;
535	        String emailPart = this.email == null ? "" : this.email;
536	        String householdPart = this.householdId == null ? "" : this.householdId;
537	        return telephonePart + "|" + emailPart + "|" + householdPart;
538	    }
