540	    /**
541	     * City -> canonical region, the fixed ground truth for deriving locality.
542	     */
543	    private static final Map<String, String> CITY_REGION = Map.of(
544	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
545	
546	    /**
547	     * Region -> inclusive 4-digit postcode range {@code {low, high}}, the fixed ground truth for
548	     * deriving locality from the postcode ahead of the city.
549	     */
550	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
551	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
552	
553	    /**
554	     * The owner's locality: the canonical region resolved by the postcode range first
555	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}), falling back to the
556	     * fixed city-to-region table ({@code Sydney->NSW}, {@code Melbourne->VIC},
557	     * {@code Brisbane->QLD}) when the postcode is absent or in no known range, or {@code "UNKNOWN"}
558	     * when the city is not in the table either. The postcode takes precedence so cities that share a
559	     * name are disambiguated by their postcode's region.
560	     *
561	     * @return the canonical region string, or {@code "UNKNOWN"}
562	     */
563	    public String getLocality() {
564	        String byPostcode = regionForPostcode(this.postcode);
565	        if (byPostcode != null) {
566	            return byPostcode;
567	        }
568	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
569	    }
570	
571	    /**
572	     * Region -> IANA timezone name, the fixed ground truth for deriving the owner's timezone from
573	     * its locality.
574	     */
575	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
576	        "NSW", "Australia/Sydney", "VIC", "Australia/Melbourne", "QLD", "Australia/Brisbane");
577	
578	    /**
579	     * The owner's timezone: the IANA name resolved from the {@link #getLocality() locality} via the
580	     * fixed region-to-timezone table ({@code NSW->Australia/Sydney}, {@code VIC->Australia/Melbourne},
581	     * {@code QLD->Australia/Brisbane}), or {@code null} when the locality is not one of these regions
582	     * (e.g. {@code "UNKNOWN"}).
583	     *
584	     * @return the IANA timezone name, or {@code null}
585	     */
586	    public String getTimezone() {
587	        return REGION_TIMEZONE.get(getLocality());
588	    }
589	
590	    /**
591	     * Region whose postcode range contains the given postcode, or {@code null} when the postcode is
592	     * absent, not a 4-digit number, or in no known range.
593	     *
594	     * @param postcode the owner's postcode (may be {@code null})
595	     * @return the matching region, or {@code null}
596	     */
597	    private static String regionForPostcode(String postcode) {
598	        if (postcode == null || !postcode.matches("\\d{4}")) {
599	            return null;
600	        }
601	        int value = Integer.parseInt(postcode);
602	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
603	            int[] range = entry.getValue();
604	            if (value >= range[0] && value <= range[1]) {
605	                return entry.getKey();
606	            }
607	        }
608	        return null;
609	    }
