92	    /**
93	     * Common address abbreviations expanded to their full form during address normalization.
94	     * Matching is performed per whitespace-separated token on the upper-cased value.
95	     */
96	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
97	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
98	
99	    /**
100	     * Required national-number length (the digits after the country code) per E.164 country code.
101	     * A number whose country code appears here must carry exactly the mapped number of national
102	     * digits; country codes not listed fall back to the generic 8-to-15 total-digit rule.
103	     */
104	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
105	        Map.of("61", 9, "1", 10);
