117	     * City -> canonical region, the fixed ground truth for deriving the region a postcode is
118	     * validated against. A city not listed here derives the {@code "UNKNOWN"} region, which imposes
119	     * no postcode-range constraint.
120	     */
121	    private static final Map<String, String> CITY_REGION = Map.of(
122	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
