315	    /**
316	     * Validates an owner's postcode against the region derived from its city. The postcode is
317	     * optional: a {@code null} value is always accepted. When present it must fall within the
318	     * inclusive range mapped to the region by {@link #REGION_POSTCODES}; a region with no known
319	     * range (e.g. the {@code "UNKNOWN"} locality of an unmapped city) accepts any 4-digit postcode.
320	     * The 4-digit syntax itself is enforced upstream by bean validation.
321	     *
322	     * @param postcode the owner's postcode (may be {@code null})
323	     * @param locality the region derived from the owner's city
324	     * @return {@code true} when the postcode is absent, the region has no range, or the postcode is
325	     *         within the region's range; {@code false} when it is out of range
326	     */
327	    /**
328	     * The canonical region for the given city via the fixed {@link #CITY_REGION} table, or
329	     * {@code "UNKNOWN"} when the city is {@code null} or not in the table.
330	     *
331	     * @param city the owner's city (may be {@code null})
332	     * @return the canonical region, or {@code "UNKNOWN"}
333	     */
334	    /**
335	     * The {@code Idempotency-Key} header of the current request, trimmed, or {@code null} when the
336	     * header is absent, blank, or no servlet request is bound to the current thread.
337	     *
338	     * @return the idempotency key, or {@code null}
339	     */
340	    private String currentIdempotencyKey() {
341	        RequestAttributes attributes = RequestContextHolder.getRequestAttributes();
342	        if (attributes instanceof ServletRequestAttributes servletAttributes) {
343	            String key = servletAttributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
344	            if (key != null && !key.isBlank()) {
345	                return key.trim();
346	            }
347	        }
348	        return null;
349	    }
