442	    /**
443	     * Whether the domain of the given normalized email is on the disposable-domain blocklist
444	     * ({@link #DISPOSABLE_EMAIL_DOMAINS}). The domain is the substring after the last {@code '@'};
445	     * an email without an {@code '@'} carries no blocked domain.
446	     *
447	     * @param email the trimmed, lower-cased email
448	     * @return {@code true} when the email's domain is blocklisted
449	     */
450	    private boolean isDisposableEmailDomain(String email) {
451	        int at = email.lastIndexOf('@');
452	        if (at < 0) {
453	            return false;
454	        }
455	        return DISPOSABLE_EMAIL_DOMAINS.contains(email.substring(at + 1));
456	    }
