458	    /**
459	     * Applies the owner's address, preferring the structured form over the flat one. When a
460	     * non-blank {@code addressLine1} is supplied the structured fields are normalized in place and
461	     * the flat {@code address} is composed as the normalized {@code addressLine1} followed, when a
462	     * non-blank {@code addressLine2} is present, by a single space and the normalized
463	     * {@code addressLine2}. Otherwise the flat {@code address} is normalized in place. An owner
464	     * that supplies neither a non-blank {@code addressLine1} nor a non-blank flat {@code address}
465	     * is invalid.
466	     *
467	     * @param owner the owner whose address fields are normalized and composed in place
468	     * @return {@code true} when a usable address was applied, {@code false} when none was supplied
469	     */
470	    private boolean applyAddress(Owner owner) {
471	        String line1 = owner.getAddressLine1();
472	        if (line1 != null && !line1.isBlank()) {
473	            String normalizedLine1 = normalizeAddress(line1);
474	            owner.setAddressLine1(normalizedLine1);
475	            String composed = normalizedLine1;
476	            String line2 = owner.getAddressLine2();
477	            if (line2 != null && !line2.isBlank()) {
478	                String normalizedLine2 = normalizeAddress(line2);
479	                owner.setAddressLine2(normalizedLine2);
480	                composed = normalizedLine1 + " " + normalizedLine2;
481	            }
482	            owner.setAddress(composed);
483	            return true;
484	        }
485	        String address = normalizeAddress(owner.getAddress());
486	        if (address == null || address.isEmpty()) {
487	            return false;
488	        }
489	        owner.setAddress(address);
490	        return true;
491	    }
