493	    /**
494	     * Normalizes a postal address for storage and comparison: surrounding whitespace is trimmed,
495	     * internal runs of whitespace are collapsed to a single space, the value is upper-cased and
496	     * common street-type abbreviations are expanded per token ({@code ST -> STREET},
497	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). The stored and returned address is this
498	     * normalized form, and every household comparison uses it.
499	     *
500	     * @param address the raw address value (may be {@code null})
501	     * @return the normalized address, or {@code null} if the input was {@code null}
502	     */
503	    private String normalizeAddress(String address) {
504	        if (address == null) {
505	            return null;
506	        }
507	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
508	        if (collapsed.isEmpty()) {
509	            return collapsed;
510	        }
511	        String[] tokens = collapsed.split(" ");
512	        StringBuilder sb = new StringBuilder(collapsed.length());
513	        for (int i = 0; i < tokens.length; i++) {
514	            if (i > 0) {
515	                sb.append(' ');
516	            }
517	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
518	        }
519	        return sb.toString();
520	    }
521	
522	    /**
523	     * Normalizes a value for household-duplicate comparison: surrounding whitespace is trimmed,
524	     * internal runs of whitespace are collapsed to a single space and the result is lower-cased,
525	     * so that owners are compared case-insensitively with collapsed whitespace.
526	     *
527	     * @param value the raw value (must not be {@code null})
528	     * @return the normalized comparison key
529	     */
530	    private String householdKey(String value) {
531	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
532	    }
533	
534	    /**
535	     * Derives a stable, shared household identifier for the owner's household: the first 12 hex
536	     * characters of the SHA-256 digest of {@code normalizedLastName + '|' + postcode}, where the
537	     * last name is normalized with {@link #householdKey} and an absent postcode is rendered as the
538	     * empty string. Because it is a pure function of the last name and postcode, every owner sharing
539	     * those two fields derives the identical identifier and therefore belongs to the same household.
540	     *
541	     * @param owner the owner whose household identifier is derived
542	     * @return the stable household identifier
543	     */
544	    private String householdId(Owner owner) {
545	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
546	        String key = householdKey(owner.getLastName()) + "|" + postcode;
547	        try {
548	            byte[] digest = MessageDigest.getInstance("SHA-256")
549	                .digest(key.getBytes(StandardCharsets.UTF_8));
550	            StringBuilder sb = new StringBuilder(digest.length * 2);
551	            for (byte b : digest) {
552	                sb.append(String.format("%02x", b));
553	            }
554	            return sb.substring(0, 12);
555	        }
556	        catch (java.security.NoSuchAlgorithmException e) {
557	            throw new IllegalStateException("SHA-256 not available", e);
558	        }
559	    }
