561	    /**
562	     * Builds the customer code for a newly registered owner in the form
563	     * {@code '<REGION>-<HASH8>'}, where {@code REGION} is the region code derived from the owner's
564	     * postcode (the same region derivation shared with {@link Owner#getLocality() locality}:
565	     * postcode range first, falling back to the city, or {@code 'UNKNOWN'}) and {@code HASH8} is the
566	     * first 8 upper-case hex characters of the SHA-256 digest of the normalized telephone
567	     * concatenated with the last name (e.g. {@code 'NSW-1A2B3C4D'}). When the computed code
568	     * collides with an existing owner's customer code, {@code '-<n>'} is appended using the
569	     * smallest {@code n} of 2 or more that makes the result unique, guaranteeing distinct owners
570	     * always receive distinct customer codes.
571	     *
572	     * @param owner the owner whose customer code is derived (with normalized telephone already set)
573	     * @return the assigned customer code
574	     */
575	    private String customerCode(Owner owner) {
576	        String region = owner.getLocality();
577	        String hash8 = sha256UpperHex(owner.getTelephone() + owner.getLastName(), 8);
578	        String base = region + "-" + hash8;
579	        Set<String> existingCodes = this.clinicService.findAllOwners().stream()
580	            .map(Owner::getCustomerCode)
581	            .filter(code -> code != null)
582	            .collect(Collectors.toSet());
583	        if (!existingCodes.contains(base)) {
584	            return base;
585	        }
586	        int n = 2;
587	        while (existingCodes.contains(base + "-" + n)) {
588	            n++;
589	        }
590	        return base + "-" + n;
591	    }
592	
593	    /**
594	     * Returns the first {@code length} upper-case hex characters of the SHA-256 digest of the
595	     * UTF-8 bytes of {@code input}.
596	     *
597	     * @param input  the value to hash
598	     * @param length the number of leading hex characters to keep
599	     * @return the truncated, upper-cased hex digest
600	     */
601	    private String sha256UpperHex(String input, int length) {
602	        try {
603	            byte[] digest = MessageDigest.getInstance("SHA-256")
604	                .digest(input.getBytes(StandardCharsets.UTF_8));
605	            StringBuilder sb = new StringBuilder(digest.length * 2);
606	            for (byte b : digest) {
607	                sb.append(String.format("%02x", b));
608	            }
609	            return sb.substring(0, length).toUpperCase(Locale.ROOT);
610	        }
611	        catch (java.security.NoSuchAlgorithmException e) {
612	            throw new IllegalStateException("SHA-256 not available", e);
613	        }
614	    }
615	
616	    /** Fixed public holidays that the business-day roll skips. */
617	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
618	        LocalDate.parse("2026-01-01"),
619	        LocalDate.parse("2026-01-26"),
620	        LocalDate.parse("2026-04-25"),
621	        LocalDate.parse("2026-12-25"),
622	        LocalDate.parse("2026-12-28"));
623	
624	    /**
625	     * Rolls a registration date forward onto a business day. When the given date falls on a
626	     * Saturday, Sunday or a listed public holiday it is advanced one day at a time until it
627	     * lands on a non-holiday weekday; a business day is returned unchanged.
628	     *
629	     * @param date the effective registration date (must not be {@code null})
630	     * @return the same date if it is already a business day, otherwise the next business day
631	     */
632	    private LocalDate toBusinessDay(LocalDate date) {
633	        while (isNonBusinessDay(date)) {
634	            date = date.plusDays(1);
635	        }
636	        return date;
637	    }
638	
639	    private boolean isNonBusinessDay(LocalDate date) {
640	        DayOfWeek dayOfWeek = date.getDayOfWeek();
641	        return dayOfWeek == DayOfWeek.SATURDAY
642	            || dayOfWeek == DayOfWeek.SUNDAY
643	            || PUBLIC_HOLIDAYS.contains(date);
644	    }
645	
646	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
647	    @Override
648	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
649	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
650	        if (currentOwner == null) {
651	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
652	        }
653	        String email = ownerFieldsDto.getEmail();
654	        if (email != null) {
655	            email = normalizeEmail(email);
656	            if (!EMAIL_PATTERN.matcher(email).matches()) {
657	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
658	            }
659	        }
660	        String telephone = toE164(ownerFieldsDto.getTelephone());
661	        if (telephone == null) {
662	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
663	        }
664	        currentOwner.setAddress(ownerFieldsDto.getAddress());
665	        currentOwner.setCity(ownerFieldsDto.getCity());
666	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
667	        currentOwner.setLastName(ownerFieldsDto.getLastName());
668	        currentOwner.setTelephone(telephone);
669	        currentOwner.setEmail(email);
670	        this.clinicService.saveOwner(currentOwner);
671	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
672	    }
673	
674	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
675	    @Transactional
676	    @Override
677	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
678	        Owner owner = this.clinicService.findOwnerById(ownerId);
679	        if (owner == null) {
680	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
681	        }
682	        // Soft-delete: flag the owner deleted and retain the record so it can still be read back.
683	        owner.setDeleted(true);
684	        this.clinicService.saveOwner(owner);
685	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
686	    }
687	
688	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
689	    @Override
690	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
691	        Owner owner = this.clinicService.findOwnerById(ownerId);
692	        if (owner == null) {
693	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
694	        }
695	        HttpHeaders headers = new HttpHeaders();
696	        Pet pet = petMapper.toPet(petFieldsDto);
697	        owner.setId(ownerId);
698	        pet.setOwner(owner);
699	        pet.getType().setName(null);
700	        this.clinicService.savePet(pet);
701	        PetDto petDto = petMapper.toPetDto(pet);
702	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
703	            .buildAndExpand(pet.getId()).toUri());
704	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
705	    }
706	
707	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
708	    @Override
709	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
710	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
711	        if (currentOwner != null) {
712	            Pet currentPet = this.clinicService.findPetById(petId);
713	            if (currentPet != null) {
714	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
715	                currentPet.setName(petFieldsDto.getName());
716	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
717	                this.clinicService.savePet(currentPet);
718	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
719	            }
720	        }
721	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
722	    }
723	
724	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
725	    @Override
726	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
727	        HttpHeaders headers = new HttpHeaders();
728	        Visit visit = visitMapper.toVisit(visitFieldsDto);
729	        Pet pet = new Pet();
730	        pet.setId(petId);
731	        visit.setPet(pet);
732	        this.clinicService.saveVisit(visit);
733	        VisitDto visitDto = visitMapper.toVisitDto(visit);
734	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
735	            .buildAndExpand(visit.getId()).toUri());
736	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
737	    }
738	
739	
740	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
741	    @Override
742	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
743	        Owner owner = this.clinicService.findOwnerById(ownerId);
744	        if (owner != null) {
745	            Pet pet = owner.getPet(petId);
746	            if (pet != null) {
747	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
748	            }
749	        }
750	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
751	    }
